const cfg = $input.first()?.json || {};
if (!cfg.apiKey) throw new Error('Config missing apiKey');
if (!cfg.locationId) throw new Error('Config missing locationId');

const apiBaseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = String(cfg.apiKey || '').trim();
const locationId = String(cfg.locationId || '').trim();
const lookbackDays = Number(cfg.lookbackDays || 30);
const sourceSystem = String(cfg.sourceSystem || 'ghl');
const calendarId = String(cfg.calendarId || '').trim();

const headers = {
  Authorization: 'Bearer ' + apiKey,
  Version: '2021-04-15',
  Accept: 'application/json',
};

const batchId = 'lt-appts-' + new Date().toISOString().replace(/[:.]/g, '-');

const end = new Date();
const start = new Date();
start.setDate(start.getDate() - lookbackDays);
const startMs = start.getTime();
const endMs = end.getTime();

// GHL: /calendars/events with calendarId, locationId, startTime(ms), endTime(ms) as query params
let url = apiBaseUrl + '/calendars/events?calendarId=' + encodeURIComponent(calendarId) + '&locationId=' + encodeURIComponent(locationId) + '&startTime=' + startMs + '&endTime=' + endMs;

let allEvents = [];

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers,
    json: true,
    timeout: 60000,
  });
  const events = Array.isArray(response?.events) ? response.events : Array.isArray(response?.data) ? response.data : [];
  allEvents = allEvents.concat(events);
} catch (error) {
  const body = error?.response?.body || error?.response?.data;
  const detail = body && typeof body === 'object' ? JSON.stringify(body) : (body || error?.message || error);
  throw new Error('GHL calendar events failed: ' + String(detail));
}

const now = new Date().toISOString();

const rows = allEvents.map(function(e) {
  const contactId = e.contactId || (e.contact && e.contact.id) || '';
  return {
    json: {
      report_date: (e.startTime || now).slice(0, 10),
      source_system: sourceSystem,
      source_key: String(e.id || ''),
      appointment_id: e.id || '',
      contact_id: contactId,
      calendar_id: e.calendarId || calendarId || '',
      assigned_user_id: e.assignedUserId || e.userId || '',
      location_id: e.locationId || '',
      title: e.title || '',
      status: e.appointmentStatus || e.status || 'booked',
      start_at: e.startTime || e.start || null,
      end_at: e.endTime || e.end || null,
      notes: e.notes || e.description || '',
      payload_json: e,
      dimensions_json: { contact_id: contactId, calendar_id: e.calendarId, status: e.appointmentStatus },
      metrics_json: {},
      batch_id: batchId,
      loaded_at: now
    }
  };
});

return rows.length > 0 ? rows : [{ json: { ok: true, skipped: true, reason: 'no_appointments_in_window', batchId, calendarId } }];

